// Generated by Cypress Author — 2026-04-27
describe('Établissement — recherche', () => {
    beforeEach(() => {
        cy.login()
    })

    it('Page chargée → formulaire de recherche visible', () => {
        cy.visit('/rechercher/etablissement')
        cy.contains('Etablissements').should('exist');
        cy.get('[name=Rechercher]').should('exist');
    });

    // Use URL query params to filter by avis — avoids fragile jQuery Multiselect interactions.
    it('Filtre "Avis favorable" → seuls les établissements favorables affichés', () => {
        cy.visit('/rechercher/etablissement?avis[]=true')
        cy.get('.avis.F').should('exist')
        cy.get('.avis.D').should('not.exist')
    });

    it('Filtre "Avis défavorable" → seuls les établissements défavorables affichés', () => {
        cy.visit('/rechercher/etablissement?avis[]=false')
        cy.get('.avis.D').should('exist')
        cy.get('.avis.F').should('not.exist')
    });

    it('Affiche la lettre, le genre et le numéro de catégorie', () => {
        cy.visit('/rechercher/etablissement?categories[]=1')
        cy.get('.categorie-etablissement')
            .should('exist')
            .first()
            .should('have.attr', 'title')
            .and('not.be.empty')
        cy.get('.categorie-etablissement').first().should('have.text', '1')
        cy.get('.lettre-type').should('exist')
        cy.get('.genre-etablissement').should('exist')
    });
});
